const { exec } = require('child_process');
const os = require('os');
const path = require('path');

const userHome = os.homedir(); 
const projectDir = path.join(userHome, "VideoEditorProject");
const scriptPath = path.join(projectDir, "merge.py");
const pythonPath = "\"C:\\Program Files\\Python313\\python.exe\""; 

return new Promise((resolve) => { // Removed 'reject' to keep n8n alive
  exec(`${pythonPath} "${scriptPath}"`, { 
    encoding: 'utf8', 
    cwd: projectDir 
  }, (error, stdout, stderr) => {

    if (error) {
      // Instead of throwing an error, we return an error object
      const errorLog = stdout ? stdout.toString() : (stderr ? stderr.toString() : error.message);

      resolve([{
        json: {
          success: false,
          status: "error",
          error_details: errorLog,
          stderr: stderr.toString()
        }
      }]);
    } else {
      resolve([{
        json: {
          success: true,
          status: "success",
          message: "Video Rendered Successfully",
          log: stdout
        }
      }]);
    }
  });
});

const { exec } = require('child_process');
const os = require('os');
const path = require('path');

// 1. Universal Paths (Bypasses Desktop & OneDrive completely!)
const userHome = os.homedir(); 
const projectDir = path.join(userHome, "VideoEditorProject");
// This automatically builds: C:\Users\Xavier\VideoEditorProject\generate.py
const scriptPath = path.join(projectDir, "generate.py");

// THE BULLETPROOF FIX:
// We must use your Python 3.13 path to match your installed libraries!
const pythonPath = "\"C:\\Program Files\\Python313\\python.exe\"";

// 2. Return a Promise (Async Mode)
// This keeps n8n "alive" while the AI generates the video
return new Promise((resolve, reject) => {

  // COMMAND: Run Python
  // We use cwd (Current Working Directory) to ensure relative paths in generate.py work
  exec(`${pythonPath} "${scriptPath}"`, { 
    encoding: 'utf8',
    cwd: projectDir 
  }, (error, stdout, stderr) => {

    if (error) {
      // If Python crashes (e.g. API error), show us the log
      const errorLog = stdout ? stdout.toString() : (stderr ? stderr.toString() : error.message);
      reject(new Error(`AI Generation Failed: ${errorLog}`));
    } else {
      // If Success, return the log
      resolve([
        {
          json: {
            status: "AI Video Generated Successfully",
            log: stdout
          }
        }
      ]);
    }

  });
});

