// 1. Grab the raw text from the AI output
let rawText = $input.first().json.content.parts[0].text;

// 2. Clean off the ```json and ``` markdown formatting
let cleanText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();

// 3. Turn it into a readable JSON object to extract the action
let aiData = JSON.parse(cleanText);

// 4. Get the original n8n item structure
let item = $input.first().json;

// 5. Expose the "action" field directly so the Switch Node can see it!
item.action = aiData.action;

// 6. Replace the messy AI text with the beautifully cleaned JSON string.
// Your "Convert to File" node will read this perfectly and save a clean prompt.txt!
item.content.parts[0].text = JSON.stringify(aiData, null, 2);

return [{ json: item }];

