const scriptPath = path.join(projectDir, "auto_subtitle.py");
const pythonPath = "\"C:\\Program Files\\Python313\\python.exe\""; 

return new Promise((resolve) => { // Removed 'reject' from here
  exec(`${pythonPath} "${scriptPath}"`, { 
    encoding: 'utf8', 
    cwd: projectDir
  }, (error, stdout, stderr) => {

    if (error) {
      // Instead of crashing n8n, we return a JSON with the error details
      const errorLog = stdout ? stdout.toString() : (stderr ? stderr.toString() : error.message);

      resolve([{
        json: {
          success: false,
          status: "error",
          error_message: "Auto Subtitles Failed",
